(6608926, 986494, 50641, '<td valign="top">great palette</td>', 'great palette', '2011-12-02 14:28:33.000000', NULL, 1),
(6608930, 986492, 10785, '<td valign="top">Great color here! I know the roots of the beech is the subject but this photo is almost lacking a focal point. Perhaps a different view point. Maybe getting a little closer and/or possibly using some local editing to brighten up the area of interest would help it pop more. I notice the mushrooms on the right hand side act as a leading line right up to the tree. Possibly getting down low and letting that line lead you right to the tree would be a great angle to shoot at! Superb color textures overall!!</td>', 'Great color here! I know the roots of the beech is the subject but this photo is almost lacking a focal point. Perhaps a different view point. Maybe getting a little closer and/or possibly using some local editing to brighten up the area of interest would help it pop more. I notice the mushrooms on the right hand side act as a leading line right up to the tree. Possibly getting down low and letting that line lead you right to the tree would be a great angle to shoot at! Superb color textures overall!!', '2011-12-02 14:32:06.000000', NULL, 1),
(6608933, 985873, 10785, '<td valign="top">Very painterly!!Lovely pastel colors in the morning!</td>', 'Very painterly!!Lovely pastel colors in the morning!', '2011-12-02 14:35:58.000000', NULL, 1),
