(6609823, 986528, 114285, '<td valign="top">Not really sure on this crop would''ve preferred to have the bottom of the tree and some of the ground, I do like the sky however.</td>', 'Not really sure on this crop would''ve preferred to have the bottom of the tree and some of the ground, I do like the sky however.', '2011-12-03 19:02:22.000000', NULL, 1),
(6609824, 986519, 114285, '<td valign="top">Wonderful, in my top picks.</td>', 'Wonderful, in my top picks.', '2011-12-03 19:02:44.000000', NULL, 1),
(6609825, 985996, 114285, '<td valign="top">Really amazing, there is light at the end of the tunnel, probably up there with the best of them in this challenge, and being in B &amp; W is a bonus, well done. 10 Ok just finished voting on all, and pretty sure this is the winner, well IMO.</td>', 'Really amazing, there is light at the end of the tunnel, probably up there with the best of them in this challenge, and being in B & W is a bonus, well done. 10 Ok just finished voting on all, and pretty sure this is the winner, well IMO.', '2011-12-03 19:03:48.000000', NULL, 1),
