(6609934, 986045, 96751, '<td valign="top">This is magnificent.  Gorgeous tones.  Seems so wise.</td>', 'This is magnificent.  Gorgeous tones.  Seems so wise.', '2011-12-04 00:04:25.000000', NULL, 1),
(6609936, 985644, 91342, '<td valign="top">Background makes this bansi image.</td>', 'Background makes this bansi image.', '2011-12-04 00:05:37.000000', NULL, 1),
(6609960, 986277, 61396, '<td valign="top">that tiny piece of land gives the whole picture a different context, so thanks for living it in.</td>', 'that tiny piece of land gives the whole picture a different context, so thanks for living it in.', '2011-12-04 01:26:50.000000', NULL, 1),
(6609962, 986462, 87808, '<td valign="top">The greens are coming across as very saturated, especially in the middle of the rock.  Amazing rock , amazing location.  Stunning in all aspects.</td>', 'The greens are coming across as very saturated, especially in the middle of the rock.  Amazing rock , amazing location.  Stunning in all aspects.', '2011-12-04 01:28:53.000000', NULL, 1),
(6609963, 986286, 87808, '<td valign="top">Fantastic photo, the processing is really nice, the only problem I see is the horizon is tilting to the right and falling off the page</td>', 'Fantastic photo, the processing is really nice, the only problem I see is the horizon is tilting to the right and falling off the page', '2011-12-04 01:29:41.000000', NULL, 1),
